// RBAC + ABAC in an ASP.NET Core handler: role gives capability, attributes constrain it
public sealed class ApproveRefundHandler : AuthorizationHandler<ApproveRefundRequirement, Refund>
{
    protected override Task HandleRequirementAsync(AuthorizationHandlerContext ctx, ApproveRefundRequirement req, Refund refund)
    {
        var u = ctx.User;
        var isRole = u.IsInRole("refund-approver");                                         // RBAC
        var sameBranch = u.FindFirst("branch")?.Value == refund.BranchCode;                 // ABAC: subject vs resource
        var withinLimit = decimal.TryParse(u.FindFirst("approval_limit")?.Value, out var limit) && refund.Amount <= limit;
        var notRequester = u.FindFirst("sub")?.Value != refund.RequestedBy;                 // SoD
        if (isRole && sameBranch && withinLimit && notRequester) ctx.Succeed(req);
        return Task.CompletedTask;
    }
}
