public sealed class EntitlementsClaimsTransformation(IEntitlementCache cache) : IClaimsTransformation
{
    public async Task<ClaimsPrincipal> TransformAsync(ClaimsPrincipal principal)
    {
        if (principal.Identity?.IsAuthenticated != true || principal.HasClaim(c => c.Type == "bank:enriched")) return principal;
        var sub = principal.FindFirst("oid")?.Value ?? principal.FindFirst("sub")!.Value;
        var ent = await cache.GetAsync(sub);                                   // cached 5 min, invalidated on change events
        var id = new ClaimsIdentity("bank-entitlements");
        id.AddClaim(new Claim("bank:enriched", "1"));
        id.AddClaim(new Claim("branch", ent.Branch));
        id.AddClaim(new Claim("approval_limit", ent.ApprovalLimit.ToString(CultureInfo.InvariantCulture)));
        foreach (var p in ent.Permissions) id.AddClaim(new Claim("perm", p));   // fine-grained, app-specific
        principal.AddIdentity(id);
        return principal;
    }
}
