public sealed class AccountAccessHandler(TimeProvider clock) : AuthorizationHandler<OperationAuthorizationRequirement, Account>
{
    protected override Task HandleRequirementAsync(AuthorizationHandlerContext ctx, OperationAuthorizationRequirement op, Account acc)
    {
        var me = Guid.Parse(ctx.User.FindFirst("customer_id")!.Value);
        var now = clock.GetUtcNow();
        var party = acc.Parties.FirstOrDefault(p => p.CustomerId == me && (p.ValidUntil is null || p.ValidUntil > now));
        var allowed = (party?.Role, op.Name) switch
        {
            (PartyRole.Owner or PartyRole.JointOwner, _)      => true,
            (PartyRole.Delegate, "View")                       => true,
            (PartyRole.Delegate, "Pay") when ctx.Resource is Account => true,   // amount checked separately against PaymentLimit
            _ => false
        };
        if (allowed) ctx.Succeed(op);
        return Task.CompletedTask;
    }
}

