app.MapPatch("/scim/v2/Users/{id}", async (string id, ScimPatchRequest patch, ClaimsPrincipal caller, TenantUsers users, ISessionRevoker sessions, CancellationToken ct) =>
{
    var tenant = caller.FindFirst("tenant_id")!.Value;                         // SCIM token scoped to one customer tenant
    var user = await users.FindAsync(tenant, id, ct);
    if (user is null) return Results.NotFound(ScimError.NotFound(id));

    foreach (var op in patch.Operations)
    {
        switch (op.Op.ToLowerInvariant(), op.Path)
        {
            case ("replace", "active") when op.Value.GetBoolean() == false:
                user.Deactivate();
                await sessions.RevokeAllAsync(tenant, user.Id, ct);              // immediate effect, not at token expiry
                break;
            case ("replace", "name.familyName"):
                user.SetFamilyName(op.Value.GetString()!);
                break;
            case ("replace", "emails[type eq \"work\"].value"):
                user.SetEmail(op.Value.GetString()!);
                break;
        }
    }
    await users.SaveAsync(user, ct);
    audit.Record("scim.user.patch", caller, user.Id, details: patch.Operations.Select(o => o.Path));
    return Results.Ok(ScimUser.From(user));
}).RequireAuthorization("scim");
