public sealed class Payment
{
    private readonly List<Approval> _approvals = [];
    public string InitiatedBy { get; private set; } = "";
    public decimal Amount { get; private set; }
    public PaymentStatus Status { get; private set; }

    public void Approve(string approverId, decimal approverLimit, DateTimeOffset at, ApprovalPolicy policy)
    {
        if (Status != PaymentStatus.PendingApproval) throw new DomainException("Not awaiting approval");
        if (approverId == InitiatedBy) throw new DomainException("Initiator cannot approve");
        if (_approvals.Any(a => a.ApproverId == approverId)) throw new DomainException("Already approved by this user");
        if (Amount > approverLimit) throw new DomainException("Amount exceeds approver limit");

        _approvals.Add(new Approval(approverId, at));
        if (_approvals.Count >= policy.RequiredApprovals(Amount)) Status = PaymentStatus.Approved;   // e.g. 2 above 50,000
    }
}
