public sealed class EntitlementCache(IEntitlementClient client, IMemoryCache cache, ILogger<EntitlementCache> log)
{
    public async Task<UserEntitlements?> GetAsync(string userId, bool sensitive, CancellationToken ct)
    {
        if (!sensitive && cache.TryGetValue(userId, out UserEntitlements? cached)) return cached;
        try
        {
            var fresh = await client.GetAsync(userId, ct);                         // sensitive operations always fetch fresh
            cache.Set(userId, fresh, TimeSpan.FromMinutes(2));
            return fresh;
        }
        catch (Exception ex) when (ex is HttpRequestException or TaskCanceledException)
        {
            log.LogWarning(ex, "Entitlement service unavailable");
            return sensitive ? null : cache.Get<UserEntitlements>(userId);         // fail closed for sensitive; documented fallback for reads
        }
    }

    public void OnEntitlementChanged(EntitlementChanged e) => cache.Remove(e.UserId);   // event-driven invalidation
}
