public async Task<RegistrationResult> CompleteAsync(RegistrationSession s, KycOutcome kyc, DeviceKeyRegistration device, CancellationToken ct)
{
    if (kyc.Status != KycStatus.Verified) return RegistrationResult.Pending("manual review");
    if (await customers.ExistsByIdentityAsync(kyc.DocumentHash, ct))                         // possible existing customer
        return RegistrationResult.RequiresLinking();                                         // strong verification path, no auto-link

    var customerId = await core.CreateCustomerAsync(kyc.ToCustomer(), ct);
    var subject = Guid.CreateVersion7();                                                    // immutable subject id
    await identities.CreateAsync(new Identity(subject, customerId, s.Email, s.Phone, emailVerified: true, phoneVerified: true), ct);
    await credentials.AddDeviceKeyAsync(subject, device.PublicKey, device.Attestation, device.DeviceId, ct);
    await events.PublishAsync(new CustomerRegistered(subject, customerId, device.DeviceId), ct);
    return RegistrationResult.Completed(subject);
}
