public sealed record MandateRule(decimal MinAmount, decimal MaxAmount, IReadOnlyList<string> RequiredGroups);   // e.g. ["A", "B"] or ["ANY", "ANY"]

public static bool IsSatisfied(MandateRule rule, IReadOnlyList<Approval> approvals)
{
    // Assign distinct approvers to required slots (small bipartite matching via backtracking)
    var slots = rule.RequiredGroups;
    var used = new bool[approvals.Count];
    return Fill(0);

    bool Fill(int slot)
    {
        if (slot == slots.Count) return true;
        for (var i = 0; i < approvals.Count; i++)
        {
            if (used[i]) continue;
            if (slots[slot] != "ANY" && !approvals[i].GroupsAtApproval.Contains(slots[slot])) continue;
            used[i] = true;
            if (Fill(slot + 1)) return true;
            used[i] = false;
        }
        return false;
    }
}
// Rule: over 100k -> ["A", "B"]; approvals [{u1: [A,B]}, {u2: [B]}] -> u1 fills A, u2 fills B -> satisfied
