// Login path: risk engine with a strict budget and a safe fallback (step-up instead of blocking everyone)
public async Task<LoginDecision> EvaluateRiskAsync(LoginContext ctx, CancellationToken ct)
{
    using var cts = CancellationTokenSource.CreateLinkedTokenSource(ct);
    cts.CancelAfter(TimeSpan.FromMilliseconds(150));
    try
    {
        var score = await risk.ScoreAsync(ctx, cts.Token);
        return score.Value > 0.8 ? LoginDecision.StepUp("high risk") : LoginDecision.Allow();
    }
    catch (OperationCanceledException) when (!ct.IsCancellationRequested)
    {
        metrics.RiskFallback.Add(1);
        return ctx.KnownDevice ? LoginDecision.Allow() : LoginDecision.StepUp("risk unavailable");   // degrade safely
    }
}
