app.MapPost("/payments/{id:guid}/release", async (Guid id, ClaimsPrincipal user, IAccessEvaluator evaluator, HttpContext http, CancellationToken ct) =>
{
    var eval = await evaluator.EvaluateAsync(user, "payments.release", ct);   // current user risk, device state, session status
    if (eval.RequiresStepUp)
    {
        var claims = new { access_token = new { acrs = new { essential = true, value = "c1" } } };
        var challenge = Convert.ToBase64String(JsonSerializer.SerializeToUtf8Bytes(claims));
        http.Response.Headers.WWWAuthenticate = $"Bearer error=\"insufficient_claims\", claims=\"{challenge}\"";
        return Results.Unauthorized();                                          // client requests a token satisfying auth context c1
    }
    if (!eval.Allowed) return Results.Forbid();
    return Results.Ok(await releaser.ReleaseAsync(id, ct));
});
