// Conceptual verifier flow: request a PID presentation with selective disclosure (OID4VP), verify, map to KYC
public async Task<KycResult> VerifyWalletPresentationAsync(string vpToken, string expectedNonce, CancellationToken ct)
{
    var presentation = await sdJwtVerifier.VerifyAsync(vpToken, new VerificationOptions
    {
        TrustedIssuers = trustList.EuPidProviders,        // from the EU trusted list
        ExpectedAudience = "https://onboarding.bank.example",
        ExpectedNonce = expectedNonce,                    // replay protection
        CheckStatusList = true                            // revocation
    }, ct);

    var claims = presentation.DisclosedClaims;           // only requested: given_name, family_name, birthdate, nationality, address
    return await kyc.CompleteFromVerifiedAttributesAsync(claims, evidence: presentation.EvidenceSummary, ct);
}
