public sealed record Consent(Guid Id, Guid CustomerId, string GranteeType, string GranteeId, IReadOnlySet<string> AccountIds,
                             IReadOnlySet<string> Permissions, DateTimeOffset? TransactionsFrom, DateTimeOffset ExpiresAt,
                             ConsentStatus Status, DateTimeOffset? LastSca);

public sealed class ConsentGuard(IConsentStore store, TimeProvider clock)
{
    public async Task<bool> AllowsAsync(string consentId, string accountId, string permission, CancellationToken ct)
    {
        var c = await store.GetAsync(consentId, ct);                         // not cached long: revocation must be immediate
        var now = clock.GetUtcNow();
        return c is { Status: ConsentStatus.Authorised }
            && c.ExpiresAt > now
            && c.AccountIds.Contains(accountId)
            && c.Permissions.Contains(permission)
            && (c.LastSca is null || now - c.LastSca < TimeSpan.FromDays(180));   // periodic re-authentication rule
    }
}
